#!/usr/bin/env python3
"""Extract ships from a grid sprite sheet generated by pixellab.ai
or similar pixel-art tools.

Auto-computes cell size from image dimensions assuming 1px borders
between cells AND around the outer edge. Cells are downscaled with
nearest-neighbor to the engine-native 24x28.

Usage:
    python3 utils/asset_extract_ship_grid.py <input.png> [output_dir]
        [--cols N] [--rows N] [--border N] [--no-downscale]

Defaults: --cols 4 --rows 3 --border 1
Outputs ship_00.png ... ship_NN.png in output_dir (default: cwd).

Examples:
    # Default 4x3 grid, auto cell size from image
    python3 utils/asset_extract_ship_grid.py grid.png ships_out/

    # 4x4 grid (e.g. AI generated 200x200 with 16 ships)
    python3 utils/asset_extract_ship_grid.py grid.png ships_out/ --cols 4 --rows 4

    # No downscale (keep original cell resolution)
    python3 utils/asset_extract_ship_grid.py grid.png ships_out/ --no-downscale
"""

import sys
from pathlib import Path

try:
    from PIL import Image
except ImportError:
    print("error: Pillow not installed. Run: pip3 install Pillow", file=sys.stderr)
    sys.exit(2)

OUT_W, OUT_H = 24, 28  # engine-native ship sprite size


def parse_int_flag(name, default):
    flag = f"--{name}"
    for i, a in enumerate(sys.argv):
        if a == flag and i + 1 < len(sys.argv):
            return int(sys.argv[i + 1])
    return default


def main():
    cols = parse_int_flag("cols", 4)
    rows = parse_int_flag("rows", 3)
    border = parse_int_flag("border", 1)
    no_downscale = "--no-downscale" in sys.argv
    if any(a in ("-h", "--help") for a in sys.argv[1:]):
        print(__doc__)
        sys.exit(0)

    # positional args (skip flag pairs)
    args = []
    skip = False
    for a in sys.argv[1:]:
        if skip:
            skip = False
            continue
        if a in ("--cols", "--rows", "--border"):
            skip = True
            continue
        if a.startswith("--"):
            continue
        args.append(a)

    if not args or len(args) > 2:
        print(__doc__, file=sys.stderr)
        sys.exit(1)

    src = Path(args[0])
    out_dir = Path(args[1]) if len(args) == 2 else Path.cwd()
    out_dir.mkdir(parents=True, exist_ok=True)

    img = Image.open(src).convert("RGBA")
    w, h = img.size

    # Compute cell size from actual image dimensions
    cell_w = (w - (cols + 1) * border) // cols
    cell_h = (h - (rows + 1) * border) // rows

    if cell_w <= 0 or cell_h <= 0:
        print(
            f"error: image {w}x{h} too small for {cols}x{rows} grid with {border}px borders",
            file=sys.stderr,
        )
        sys.exit(1)

    # Sanity check: how much pixel slack vs perfect fit
    used_w = cols * cell_w + (cols + 1) * border
    used_h = rows * cell_h + (rows + 1) * border
    slack_w, slack_h = w - used_w, h - used_h

    print(f"image: {w}x{h}, grid: {cols}x{rows}, border: {border}px")
    print(f"computed cell size: {cell_w}x{cell_h} (slack {slack_w}x{slack_h}px)")

    count = 0
    for row in range(rows):
        for col in range(cols):
            x = border + col * (cell_w + border)
            y = border + row * (cell_h + border)
            cell = img.crop((x, y, x + cell_w, y + cell_h))
            if not no_downscale and (cell_w, cell_h) != (OUT_W, OUT_H):
                cell = cell.resize((OUT_W, OUT_H), Image.NEAREST)
            out = out_dir / f"ship_{row * cols + col:02d}.png"
            cell.save(out)
            count += 1

    sized = "(--no-downscale)" if no_downscale else f"(downscaled to {OUT_W}x{OUT_H})"
    print(f"extracted {count} ships to {out_dir}/ {sized}")


if __name__ == "__main__":
    main()
